import React, { useState } from 'react';
import OTPInput from '../components/OTPInput';
import '../components/OTPInput.css';
import './TwoFAPage.css';

const TwoFAPage = () => {
  const [code, setCode] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // normally send to backend or update state
    console.log('submitted 2FA code', code);
  };

  return (
    <div className="twofa-container">
      <form className="twofa-form" onSubmit={handleSubmit}>
        <img
          src="/images/facebook_logo.svg"
          alt="Facebook"
          className="fb-logo"
        />
        <h2>Go to your authentication app</h2>
        <p className="twofa-desc">
          Enter the 6‑digit code for this account from the two‑factor
          authentication app that you set up (such as Duo Mobile or Google
          Authenticator).
        </p>
        <OTPInput
          length={6}
          value={code}
          onChange={setCode}
          error={false}
        />
        <button
          type="submit"
          className="btn continue-btn"
          disabled={code.length < 6}
        >
          Continue
        </button>
        <button type="button" className="btn try-other-btn">
          Try Another Way
        </button>
      </form>
    </div>
  );
};

export default TwoFAPage;
